import pandas as pd
import numpy as np
import random

DATASET_PATH = 'chunks_csv/moran_local_2021_gas.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

gas_df = pd.read_csv(DATASET_PATH)
adj_df = pd.read_csv(ADJACENCY_PATH)

borough_neighbors = {}
for _, row in adj_df.iterrows():
    b = row['borough']
    n = row['neighbor']
    if b not in borough_neighbors:
        borough_neighbors[b] = []
    if n not in borough_neighbors:
        borough_neighbors[n] = []
    if n not in borough_neighbors[b]:
        borough_neighbors[b].append(n)
    if b not in borough_neighbors[n]:
        borough_neighbors[n].append(b)

for b in borough_neighbors:
    borough_neighbors[b] = list(set(borough_neighbors[b]))

observed_diffs = {}
for borough in gas_df['borough']:
    gas = gas_df.loc[gas_df['borough'] == borough, 'Gas_value'].values[0]
    neighbors = borough_neighbors.get(borough, [])
    if not neighbors:
        observed_diffs[borough] = None
        continue
    neighbor_gas = [gas_df.loc[gas_df['borough'] == n, 'Gas_value'].values[0] for n in neighbors]
    avg_neighbor = np.mean(neighbor_gas)
    observed_diffs[borough] = gas - avg_neighbor

num_permutations = 500
permuted_diffs = {borough: [] for borough in gas_df['borough']}

for _ in range(num_permutations):
    shuffled_gas = gas_df['Gas_value'].sample(frac=1).reset_index(drop=True)
    for borough in gas_df['borough']:
        idx = gas_df[gas_df['borough'] == borough].index[0]
        gas = shuffled_gas[idx]
        neighbors = borough_neighbors.get(borough, [])
        if not neighbors:
            continue
        neighbor_gas = [shuffled_gas[gas_df[gas_df['borough'] == n].index[0]] for n in neighbors]
        avg_neighbor = np.mean(neighbor_gas)
        permuted_diffs[borough].append(gas - avg_neighbor)

hot_cold_spots = []
for borough in gas_df['borough']:
    observed_diff = observed_diffs[borough]
    if observed_diff is None:
        continue
    permuted_list = permuted_diffs[borough]
    if observed_diff > 0:
        count = sum(1 for d in permuted_list if d >= observed_diff)
        p_value = count / num_permutations
        if p_value < 0.05:
            hot_cold_spots.append((borough, 'HH', observed_diff))
    else:
        count = sum(1 for d in permuted_list if d <= observed_diff)
        p_value = count / num_permutations
        if p_value < 0.05:
            hot_cold_spots.append((borough, 'LL', observed_diff))

final_answer = []
for item in hot_cold_spots:
    borough_name, category, diff = item
    final_answer.append(f"{borough_name} ({category}, statistical method={diff:.2f})")

print("FINAL ANSWER: " + ", ".join(final_answer) if final_answer else "FINAL ANSWER: none")
